SELECT CAST(r.id AS CHAR) AS id, CAST(r.application_id AS CHAR) AS applicationId, CAST(r.process_id AS CHAR) AS processId, CAST(r.process_version_id AS CHAR) AS processVersionId, r.process_code AS processCode, p.process_name AS processName, r.subject_object_code AS subjectObjectCode, r.subject_record_id AS subjectRecordId, r.business_key AS businessKey, r.trigger_type AS triggerType, r.actor_type AS actorType, CAST(r.actor_user_id AS CHAR) AS actorUserId, CAST(r.active_org_id AS CHAR) AS activeOrgId, r.status AS status, r.current_node_id AS currentNodeId, r.retry_count AS retryCount, r.error_code AS errorCode, r.error_summary AS errorSummary, r.start_time AS startTime, r.end_time AS endTime, r.create_time AS createTime, r.update_time AS updateTime FROM ai_business_process_run r LEFT JOIN ai_business_process p ON p.tenant_id = r.tenant_id AND p.id = r.process_id AND p.del_flag = 0 WHERE r.tenant_id = #{tenantId}
AND r.application_id = #{query.applicationId}
AND r.process_id = #{query.processId}
AND r.subject_object_code = #{query.subjectObjectCode}
AND r.subject_record_id = #{query.subjectRecordId}
AND r.status = #{query.status}
AND r.trigger_type = #{query.triggerType}
AND r.create_time >= #{query.startTime}
AND r.create_time <= #{query.endTime}
ORDER BY r.create_time DESC, r.id DESC

