ORDER BY create_time DESC, id DESC
LIMIT 1

SELECT 
FROM ai_business_process_run
WHERE tenant_id = #{tenantId}
  AND application_id = #{applicationId}
  AND subject_object_code = #{objectCode}
  AND subject_record_id = #{recordId}
  AND flow_process_instance_id IS NOT NULL
  AND flow_process_instance_id != ''
ORDER BY create_time DESC, id DESC
LIMIT 1

SELECT COUNT(1)
FROM ai_business_process_run
WHERE tenant_id = #{tenantId}
  AND process_id = #{processId}
  AND status IN ('PENDING', 'RUNNING', 'WAITING')

