UPDATE ai_business_process_run SET status = #{nextStatus}, current_node_id = #{currentNodeId}, flow_process_instance_id = #{processInstanceId}, next_retry_time = #{nextRetryTime}, error_code = #{errorCode}, error_summary = #{errorSummary}, start_time = CASE WHEN #{nextStatus} = 'RUNNING' AND start_time IS NULL THEN NOW() ELSE start_time END, end_time = CASE WHEN #{nextStatus} IN ('SUCCESS', 'FAILED', 'CANCELED') THEN NOW() ELSE NULL END, update_time = NOW() WHERE tenant_id = #{tenantId} AND id = #{runId} AND status = #{expectedStatus}
AND current_node_id = #{expectedCurrentNodeId}
AND current_node_id IS NULL
AND flow_process_instance_id = #{expectedProcessInstanceId}
AND flow_process_instance_id IS NULL
